+	// 写成字符串的 "1e400" 是合法属性值，原样参与字符串比较。
+	ctx := mustParseContext(t, `{"a":"1e400"}`)
+	if v, ok := ctx.Get("a"); !ok || v != "1e400" {
+		t.Fatalf("string-quoted big number must stay a string: %q %v", v, ok)
